// Stops the run while a setting is still a sample or makes no sense, before anything is read, saved or sent.
// Then it hands on what the entry point delivered (the order, the replies, or nothing for a timer), marked with
// where it came from.
const cfg = $('Your settings').first().json;
const problems = [];
// Where this run came from decides what is checked: the time zone only matters to the two timers (sending hours and
// the week of the report). An order and a reply never depend on it, so a zone mismatch can never lose an order or a STOP.
const source = $('Receive an order').isExecuted ? 'order' : $('Poll WhatsApp replies').isExecuted ? 'reply' : $('Every week: send the NPS report').isExecuted ? 'report' : 'timer';
const text = (name) => String(cfg[name] ?? '').trim();
const E164 = /^\+[1-9]\d{7,14}$/;
const HHMM = /^([01]\d|2[0-3]):[0-5]\d$/;

if (!E164.test(text('owner_phone'))) problems.push('owner_phone is not a real number yet (your own WhatsApp number, with + and the country code)');
if (!text('business_name') || text('business_name') === 'Your Business Name') problems.push('business_name is still the sample');
if (!text('number_alias')) problems.push('number_alias is empty (main, the alias or the num_ id of the number that sends)');
if ((source === 'timer' || source === 'report') && $now.zoneName !== text('expected_timezone')) {
  problems.push('Time zone mismatch: this workflow runs in ' + $now.zoneName + ' but expected_timezone in Your settings is ' + text('expected_timezone') + '. Set the workflow time zone (Workflow settings, Timezone) and expected_timezone to the same zone');
}
const number = (name, whole, min) => {
  const value = Number(cfg[name]);
  if (text(name) === '' || !Number.isFinite(value) || value < min || (whole && !Number.isInteger(value))) {
    problems.push(name + ' must be a ' + (whole ? 'whole ' : '') + 'number of ' + min + ' or more');
  }
};
number('delay_hours', false, 0);
number('cooldown_days', false, 0);
number('max_surveys_per_day', true, 1);
number('max_surveys_per_run', true, 1);
number('close_after_days', false, 1);
number('max_text_length', true, 10);
number('max_comment_length', true, 20);
if (!(Number(cfg.purge_days) === 0 || (Number.isInteger(Number(cfg.purge_days)) && Number(cfg.purge_days) >= 60)) || text('purge_days') === '') {
  problems.push('purge_days must be 0 (never delete) or a whole number of 60 or more');
}
if (!HHMM.test(text('window_start')) || !HHMM.test(text('window_end')) || text('window_start') >= text('window_end')) {
  problems.push('window_start and window_end must be times like 09:00 and 20:00, the start before the end');
}
if (!/^\d{1,4}$/.test(text('default_country_code'))) problems.push('default_country_code must be digits, for example 55');
const list = (name) => text(name).split(',').map((word) => word.trim()).filter(Boolean);
if (list('start_statuses').length === 0) problems.push('start_statuses is empty: no order would start a survey');
if (list('optout_words').length === 0) problems.push('optout_words is empty: a customer could not stop the questions');
for (const name of ['field_order_id', 'field_customer_name', 'field_phone', 'field_status', 'field_order_url', 'field_items']) {
  if (!text(name)) problems.push(name + ' is empty: name the field of your order that holds it');
}
if (!['everyone', 'promoters'].includes(text('review_for').toLowerCase())) problems.push('review_for must be everyone or promoters');
const review = text('review_url');
if (review && (review.length > 500 || !/^https?:\/\/\S+$/i.test(review))) problems.push('review_url must be empty or a web address starting with http:// or https:// (500 characters at most)');
const button = text('review_button_text');
if (!button || button.length > 20) problems.push('review_button_text must be 1 to 20 characters');
for (const name of ['name_fallback', 'msg_question', 'msg_reask', 'msg_promoter', 'msg_passive', 'msg_detractor', 'msg_comment_thanks', 'msg_optout_confirm', 'msg_owner_alert', 'msg_owner_comment', 'msg_report']) {
  if (!text(name)) problems.push(name + ' is empty');
}
if (review && !text('msg_review_invite')) problems.push('msg_review_invite is empty (it goes with the review button)');

if (problems.length > 0) {
  throw new Error('Not ready to survey anybody: ' + problems.join('; ') + '. Fix Your settings, then the workflow runs.');
}

const items = source === 'order' ? $('Receive an order').all() : source === 'reply' ? $('Poll WhatsApp replies').all() : [{ json: {} }];
return items.map((item) => ({ json: { ...item.json, source } }));

// Decides what this run has to do. Nothing is sent or saved here. It returns PLANS: one per row to save, each with
// the messages to send for that row. For replies it returns the events worth reading in full instead (the next
// nodes read the whole text, then decide). The input is the rows of the table.
const cfg = $('Your settings').first().json;
const source = $('Check the settings').first().json.source;
const incoming = $('Check the settings').all().map((item) => item.json);
const COLUMNS = ['order_id', 'customer_name', 'phone', 'status', 'score', 'comment', 'asked_at', 'answered_at', 'due_at', 'message_id', 'category', 'created_at', 'reasks', 'note', 'order_url', 'items'];
const blankRow = () => ({ order_id: '', customer_name: '', phone: '', status: '', score: null, comment: '', asked_at: '', answered_at: '', due_at: '', message_id: '', category: '', created_at: '', reasks: 0, note: '', order_url: '', items: '' });
const pick = (row) => {
  const out = blankRow();
  for (const name of COLUMNS) if (row[name] !== undefined && row[name] !== null) out[name] = row[name];
  out.score = row.score === undefined || row.score === null || row.score === '' ? null : Number(row.score);
  out.reasks = Number(row.reasks) || 0;
  return out;
};
const DAY = (24 * 3600000);
const list = (value) => String(value ?? '').split(',').map((word) => word.trim().toLowerCase()).filter(Boolean);
const digits = (value) => String(value ?? '').replace(/\D/g, '');
const fold = (value) => String(value ?? '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
// Control characters, zero-width and bidirectional marks become spaces (written as escapes on purpose).
const clean = (value, max) => String(value ?? '').replace(/[\u0000-\u001f\u007f\u200b-\u200f\u202a-\u202e\u2060-\u206f\ufeff]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
// The words that opt a customer out: a WHOLE message, capitals, accents and punctuation do not matter.
const stopWords = list(cfg.optout_words).map((word) => fold(word).replace(/[^a-z0-9]+/g, ' ').trim()).filter(Boolean);
const isStop = (text) => stopWords.includes(fold(text).replace(/[^a-z0-9]+/g, ' ').trim());
const rows = $input.all().map((item) => item.json).filter((row) => row && row.order_id).map(pick);
const nowMs = Date.now();
const nowIso = new Date(nowMs).toISOString();
const ageMs = (iso) => (Date.parse(iso) ? nowMs - Date.parse(iso) : Infinity);
const plan = (row, messages) => ({ json: { row, messages: messages || [] } });
const safe = (value) => String(value).replace(/[^A-Za-z0-9._-]/g, '_');
const say = (purpose, row, vars) => ({
  purpose,
  to: row.phone,
  key: 'nps-' + purpose + '-' + safe(row.order_id),
  vars: { customer_name: row.customer_name, order_id: row.order_id, items: row.items, order_url: row.order_url, ...vars },
});

// ---------------------------------------------------------------- a new order
if (source === 'order') {
  const hook = incoming[0] || {};
  const body = hook.body && typeof hook.body === 'object' && !Array.isArray(hook.body) ? hook.body : null;
  if (!body) throw new Error('Order rejected: the request has no JSON object in its body.');
  const field = (setting) => body[String(cfg[setting]).trim()];
  const max = Math.floor(Number(cfg.max_text_length));
  const hasLink = (value) => /https?:|www\.|@\d/i.test(value);

  const orderId = clean(field('field_order_id'), 65);
  if (!/^[A-Za-z0-9._#:-]{1,64}$/.test(orderId)) {
    throw new Error('Order rejected: the field "' + cfg.field_order_id + '" must hold an order id of 1 to 64 letters, digits or . _ # : - (got ' + (orderId ? orderId.length + ' characters' : 'nothing') + ').');
  }
  // The table uses these prefixes for its own rows (the weekly report, a STOP marker, a note about a status).
  if (/^(report|optout|status)-/i.test(orderId)) {
    throw new Error('Order rejected: an order id may not start with report-, optout- or status- (the table uses those for its own rows).');
  }
  const status = clean(field('field_status'), 40).toLowerCase();
  const starts = list(cfg.start_statuses);
  if (!starts.includes('*') && !starts.includes(status)) {
    // Another event of the order (created, paid, cancelled, refunded) starts nothing. It is never silent: a row says which
    // status arrived, so a status that matches nothing is seen at once. The row has no phone and no name. There are 20
    // slots (status-01 to status-20, picked from the order id): a newer order overwrites an older one in its slot, so
    // the table cannot fill up with them and the latest ones are always there.
    const slot = [...orderId].reduce((hash, char) => Math.imul(hash ^ char.charCodeAt(0), ((1 << 24) + 0x193)) >>> 0, 0x811c9dc5) % 20 + 1;
    const noteId = 'status-' + String(slot).padStart(2, '0');
    const why = 'order ' + orderId + ': ' + (status ? 'status "' + status + '" does not start a survey' : 'the field "' + cfg.field_status + '" is empty or missing') + ' (start_statuses: ' + starts.join(', ') + ')';
    return [plan({ ...blankRow(), order_id: noteId, status: 'skipped', note: why.slice(0, 300), created_at: nowIso })];
  }

  let name = clean(field('field_customer_name'), max);
  if (hasLink(name)) name = '';
  const rawItems = field('field_items');
  const itemNames = (Array.isArray(rawItems) ? rawItems : [rawItems]).map((item) => (item && typeof item === 'object' ? item.name ?? item.title ?? '' : item));
  let items = clean(itemNames.map((item) => clean(item, max)).filter(Boolean).join(', '), max);
  if (hasLink(items)) items = '';
  const link = clean(field('field_order_url'), 501);
  const orderUrl = link.length <= 500 && /^https?:\/\/\S+$/i.test(link) ? link : '';

  // Phone: E.164 only where it is unambiguous. Local formats get default_country_code only for 55 (Brazil: the area
  // code and the 9 digit mobile number are needed). With another code, only numbers that start with that code or
  // with + are accepted: a leading 0 or a trunk prefix cannot be told apart from the number itself.
  const country = String(cfg.default_country_code || '55').replace(/\D/g, '');
  const international = (all) => {
    if (!/^[1-9]\d{7,14}$/.test(all)) return { error: 'not a valid international number' };
    if (all.startsWith('55') && !(all.length === 13 && all[4] === '9')) return { error: 'a Brazilian mobile number is the country code 55, the area code, then 9 and 8 more digits' };
    return { phone: '+' + all };
  };
  const toE164 = (raw) => {
    const typed = String(raw ?? '').trim().replace(/[\s().-]/g, '');
    if (!/^\+?\d+$/.test(typed)) return { error: 'not digits' };
    if (typed.startsWith('+')) return international(typed.slice(1));
    if (typed.startsWith('00')) return international(typed.slice(2));
    let all = typed;
    if (country === '55') {
      all = all.replace(/^0(?=\d{10,11}$)/, '');
      if (/^55\d{11}$/.test(all)) return international(all);
      if (/^[1-9][1-9]9\d{8}$/.test(all)) return international('55' + all);
      return { error: 'a local number needs the area code and the 9 digit mobile number, or must start with + and the country code' };
    }
    if (all.startsWith(country)) return international(all);
    return { error: 'must start with + and the country code' };
  };

  // The same order again (the shop sent the event twice, or both paid and delivered) is ignored.
  if (rows.some((row) => row.order_id === orderId)) return [];

  const row = { ...blankRow(), order_id: orderId, customer_name: name, order_url: orderUrl, items, created_at: nowIso };
  const parsed = toE164(field('field_phone'));
  if (parsed.error) {
    return [plan({ ...row, status: 'skipped', note: 'invalid phone (' + parsed.error + '): ' + clean(field('field_phone'), 30) })];
  }
  const phone = parsed.phone;
  if (rows.some((other) => other.phone === phone && other.status === 'opted_out')) {
    return [plan({ ...row, phone, status: 'skipped', note: 'the customer opted out' })];
  }
  const cooldownMs = Number(cfg.cooldown_days) * DAY;
  const recent = rows.find((other) => other.phone === phone && ['queued', 'asked', 'answered', 'commented', 'closed'].includes(other.status) && ageMs(other.created_at) < cooldownMs);
  if (recent) {
    return [plan({ ...row, phone, status: 'skipped', note: 'already surveyed in the last ' + cfg.cooldown_days + ' days (order ' + recent.order_id + ')' })];
  }
  return [plan({ ...row, phone, status: 'queued', due_at: new Date(nowMs + Number(cfg.delay_hours) * 3600000).toISOString() })];
}

// ---------------------------------------------------------------- every 15 minutes: close what is old, ask what is due
if (source === 'timer') {
  const out = [];
  const closeMs = Number(cfg.close_after_days) * DAY;
  const minutes = $now.hour * 60 + $now.minute;
  const [from, to] = [cfg.window_start, cfg.window_end].map((value) => { const [h, m] = String(value).split(':').map(Number); return h * 60 + m; });
  const inWindow = minutes >= from && minutes < to;
  const dayStart = $now.startOf('day').toMillis();
  const changed = new Set();
  const close = (row, patch) => { changed.add(row.order_id); out.push(plan({ ...row, ...patch })); };

  for (const row of rows) {
    if (row.status === 'asked' && ageMs(row.asked_at) >= closeMs) close(row, { status: 'closed', note: 'no answer in ' + cfg.close_after_days + ' days' });
    else if (row.status === 'answered' && ageMs(row.answered_at) >= closeMs) close(row, { status: 'closed', note: 'no comment in ' + cfg.close_after_days + ' days' });
    else if (row.status === 'queued' && ageMs(row.due_at) >= closeMs) close(row, { status: 'skipped', note: 'not sent in time' });
  }

  if (inWindow) {
    // One open question per customer: whoever still owes an answer is not asked about another order.
    const busy = new Set(rows.filter((row) => (row.status === 'asked' || row.status === 'answered') && !changed.has(row.order_id)).map((row) => row.phone));
    // A question that was marked as asked but never confirmed (n8n stopped in between) is sent again with the SAME
    // idempotency key: Turbo Notify returns the first message when it did go out.
    for (const row of rows) {
      if (row.status === 'asked' && !changed.has(row.order_id) && !row.message_id && row.reasks === 0 && ageMs(row.asked_at) >= 120000) {
        out.push(plan(row, [say('question', row)]));
      }
    }
    // At most max_surveys_per_day a day AND max_surveys_per_run at a time: the window opening with a backlog must not
    // send a burst of first messages to people who never wrote to the number.
    let room = Math.floor(Number(cfg.max_surveys_per_day)) - rows.filter((row) => row.asked_at && Date.parse(row.asked_at) >= dayStart).length;
    room = Math.min(room, Math.floor(Number(cfg.max_surveys_per_run)));
    const due = rows
      .filter((row) => row.status === 'queued' && !changed.has(row.order_id) && Date.parse(row.due_at) <= nowMs)
      .sort((a, b) => Date.parse(a.due_at) - Date.parse(b.due_at));
    for (const row of due) {
      if (room <= 0) break;
      if (busy.has(row.phone)) continue;
      busy.add(row.phone);
      room -= 1;
      out.push(plan({ ...row, status: 'asked', asked_at: nowIso, note: '' }, [say('question', row)]));
    }
  }
  return out;
}

// ---------------------------------------------------------------- once a week: the NPS report for the owner
if (source === 'report') {
  const weekId = $now.weekYear + '-W' + String($now.weekNumber).padStart(2, '0');
  const reportId = 'report-' + weekId;
  // Once a week old rows go, when purge_days is set: the closed, skipped and failed ones. Never a STOP (opted_out), and
  // never a survey that is still open: the delete node excludes them.
  const purge = Number(cfg.purge_days) > 0 ? [{ json: { purge: true, cutoff: new Date(nowMs - Number(cfg.purge_days) * DAY).toISOString() } }] : [];
  if (rows.some((row) => row.order_id === reportId)) return purge; // this week's report went out already
  const days = 7;
  const since = nowMs - days * DAY;
  const surveys = rows.filter((row) => !/^(report|optout|status)-/.test(row.order_id));
  const within = (iso) => Date.parse(iso) >= since;
  const asked = surveys.filter((row) => row.asked_at && within(row.asked_at)).length;
  const answered = surveys.filter((row) => row.answered_at && within(row.answered_at) && row.score !== null);
  const count = (category) => answered.filter((row) => row.category === category).length;
  const [promoters, passives, detractors] = [count('promoter'), count('passive'), count('detractor')];
  const first = (value) => String(value || '').split(' ')[0] || 'a customer';
  const comments = answered
    .filter((row) => row.category === 'detractor' && row.comment)
    .sort((a, b) => Date.parse(b.answered_at) - Date.parse(a.answered_at))
    .slice(0, 3)
    .map((row) => '- ' + first(row.customer_name) + ' (' + row.score + '/10): ' + row.comment.slice(0, 160));
  const ids = (rowsOf) => rowsOf.slice(0, 5).map((row) => row.order_id).join(', ') + (rowsOf.length > 5 ? ' and ' + (rowsOf.length - 5) + ' more' : '');
  const failed = surveys.filter((row) => row.status === 'send_failed' && within(row.created_at));
  const skipped = surveys.filter((row) => row.status === 'skipped' && String(row.note).startsWith('invalid phone') && within(row.created_at));
  const vars = {
    days,
    asked,
    answered: answered.length,
    rate: asked > 0 ? Math.round((100 * answered.length) / asked) : 0,
    nps: answered.length > 0 ? Math.round((100 * (promoters - detractors)) / answered.length) : 'n/a',
    promoters,
    passives,
    detractors,
    comments: comments.length > 0 ? comments.join('\n') : 'none',
    failed: failed.length > 0 ? failed.length + ' (orders ' + ids(failed) + ')' : 'none',
    skipped: skipped.length > 0 ? skipped.length + ' (orders ' + ids(skipped) + ')' : 'none',
  };
  const row = { ...blankRow(), order_id: reportId, customer_name: 'Weekly report', status: 'closed', note: 'weekly report', created_at: nowIso };
  return [...purge, plan(row, [{ purpose: 'report', to: String(cfg.owner_phone).trim(), key: 'nps-report-' + weekId, vars }])];
}

// ---------------------------------------------------------------- replies: only from customers who owe an answer (or who say STOP)
const ownerDigits = digits(cfg.owner_phone);
// Only the number that sends the questions: with several numbers on the account a customer who writes to another one
// is not answering a survey. The setting is main, an alias or a num_ id; the event carries the alias and the id.
const wanted = fold(String(cfg.number_alias).trim());
const onNumber = (event) => (!event.number_id && !event.number_alias) || fold(event.number_id) === wanted || fold(event.number_alias) === wanted;
// A message whose content expired reaches the poll with a marker in place of its text: it is never read as an answer.
const REDACTED = /^\[content redacted/i;
const byPhone = new Map();
for (const row of rows) if (row.phone) byPhone.set(row.phone, [...(byPhone.get(row.phone) || []), row]);
const picks = [];
for (const [index, event] of incoming.entries()) {
  const d = event.data || {};
  if (event.type !== 'message.received' && event.type !== 'message.replied') continue;
  if (!onNumber(event)) continue;
  if (d.direction !== 'inbound' || (d.to && d.to.group_id) || d.content_type !== 'text') continue; // private text written by a person
  if (REDACTED.test(String(d.preview ?? ''))) continue;
  const from = digits(d.from && d.from.number); // a sender whose number WhatsApp hides has none: it cannot be matched to a survey and is ignored
  if (!from || from === digits(d.to && d.to.number) || from === ownerDigits) continue;
  const phone = '+' + from;
  const mine = byPhone.get(phone) || [];
  const waiting = mine.some((row) => row.status === 'asked' || row.status === 'answered');
  const stops = isStop(d.preview) && mine.length > 0 && !mine.some((row) => row.status === 'opted_out');
  if (!waiting && !stops) continue; // chat that has nothing to do with a survey is never answered
  picks.push({ json: { pick: true, event_id: event.id, message_id: d.id || '', number_id: event.number_id || '', phone, preview: String(d.preview ?? ''), at: d.at || event.created_at || '', order: index } });
}
// Oldest first, so that two messages of the same customer are judged in the order they were written.
return picks.sort((a, b) => (Date.parse(a.json.at) || 0) - (Date.parse(b.json.at) || 0) || a.json.order - b.json.order);

// Judges the replies of this poll, one after the other, oldest first, so two messages of the same customer are
// handled in the order they were written. Each reply is matched with the survey that is waiting for it. Nothing is
// sent or saved here: it returns PLANS (a row to save and the messages to send for it).
const cfg = $('Your settings').first().json;
const picks = $('Decide what to do').all().map((item) => item.json);
const read = $input.all().map((item) => item.json); // the whole messages, in the same order as the picks
const COLUMNS = ['order_id', 'customer_name', 'phone', 'status', 'score', 'comment', 'asked_at', 'answered_at', 'due_at', 'message_id', 'category', 'created_at', 'reasks', 'note', 'order_url', 'items'];
const blankRow = () => ({ order_id: '', customer_name: '', phone: '', status: '', score: null, comment: '', asked_at: '', answered_at: '', due_at: '', message_id: '', category: '', created_at: '', reasks: 0, note: '', order_url: '', items: '' });
const pick = (row) => {
  const out = blankRow();
  for (const name of COLUMNS) if (row[name] !== undefined && row[name] !== null) out[name] = row[name];
  out.score = row.score === undefined || row.score === null || row.score === '' ? null : Number(row.score);
  out.reasks = Number(row.reasks) || 0;
  return out;
};
const DAY = (24 * 3600000);
const list = (value) => String(value ?? '').split(',').map((word) => word.trim().toLowerCase()).filter(Boolean);
const digits = (value) => String(value ?? '').replace(/\D/g, '');
const fold = (value) => String(value ?? '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
// Control characters, zero-width and bidirectional marks become spaces (written as escapes on purpose).
const clean = (value, max) => String(value ?? '').replace(/[\u0000-\u001f\u007f\u200b-\u200f\u202a-\u202e\u2060-\u206f\ufeff]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
// The words that opt a customer out: a WHOLE message, capitals, accents and punctuation do not matter.
const stopWords = list(cfg.optout_words).map((word) => fold(word).replace(/[^a-z0-9]+/g, ' ').trim()).filter(Boolean);
const isStop = (text) => stopWords.includes(fold(text).replace(/[^a-z0-9]+/g, ' ').trim());
const nowIso = new Date().toISOString();
const safe = (value) => String(value).replace(/[^A-Za-z0-9._-]/g, '_');
const surveys = new Map($('Read the surveys').all().map((item) => item.json).filter((row) => row && row.order_id).map((row) => [row.order_id, pick(row)]));
const plans = new Map(); // order_id -> { row, messages }
const save = (row) => {
  surveys.set(row.order_id, row);
  if (!plans.has(row.order_id)) plans.set(row.order_id, { row, messages: [] });
  plans.get(row.order_id).row = row;
