const say = (entry, purpose, to, extra) => entry.messages.push({
  purpose,
  to,
  key: purpose === 'optout' ? 'nps-stop-' + digits(to) : 'nps-' + purpose + '-' + safe(entry.row.order_id),
  vars: { customer_name: entry.row.customer_name, phone: entry.row.phone, order_id: entry.row.order_id, items: entry.row.items, order_url: entry.row.order_url, score: entry.row.score, category: entry.row.category, comment: entry.row.comment, ...extra },
});

// A score is ONE whole number from 0 to 10, as digits ("9", "9 !", "10/10", "7 out of 10", "nota 8") or as a word in
// English or Portuguese ("nine", "dez", "ten out of ten"). Two different numbers, a decimal, a number above 10
// ("100%") or no number at all is not a score: it gets one gentle re-ask.
const WORDS = { zero: 0, one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10, um: 1, uma: 1, dois: 2, duas: 2, tres: 3, quatro: 4, cinco: 5, seis: 6, sete: 7, oito: 8, nove: 9, dez: 10 };
const WEAK = new Set(['one', 'um', 'uma']); // also ordinary words: counted only in a very short message (two words or fewer)
const parseScore = (raw) => {
  const text = fold(raw).replace(/(\d{1,2})\s*(?:\/|out of|de)\s*10(?!\d)/g, '$1');
  if (/\d[.,]\d/.test(text)) return null;
  const found = new Set([...text.matchAll(/(?<!\d)\d{1,3}(?!\d)/g)].map((match) => Number(match[0])));
  if (found.size === 0 && !/\d/.test(text)) {
    const tokens = text.match(/[a-z]+/g) || [];
    for (const token of tokens) {
      if (Object.hasOwn(WORDS, token) && (!WEAK.has(token) || tokens.length <= 2)) found.add(WORDS[token]);
    }
  }
  if (found.size !== 1) return null;
  const [score] = [...found];
  return score >= 0 && score <= 10 ? score : null;
};
// A sentence next to the score ("nota 10, entrega rapida e atendimento otimo") is already the comment.
const hasSentence = (raw) => {
  const words = (clean(raw, 1000).replace(/\d+\s*(?:\/|out of|de)\s*10/gi, ' ').replace(/\d+/g, ' ').match(/\p{L}{2,}/gu) || []).filter((word) => !Object.hasOwn(WORDS, fold(word)));
  return words.length >= 4;
};
const categoryOf = (score) => (score >= 9 ? 'promoter' : score >= 7 ? 'passive' : 'detractor');

for (const [index, event] of picks.entries()) {
  const message = read[index] || {};
  // A message whose content expired (the plan keeps the text for a limited time) has no text and a marker for a preview:
  // it is never read as an answer. The survey stays as it was and closes by itself after close_after_days.
  if (message.content_expired === true || /^\[content redacted/i.test(String(event.preview ?? ''))) continue;
  const whole = typeof message.text === 'string' && message.text.trim() ? message.text : event.preview; // the poll only carries the first 50 characters
  const text = clean(whole, Math.floor(Number(cfg.max_comment_length)));
  const mine = [...surveys.values()].filter((row) => row.phone === event.phone);

  if (isStop(text)) {
    if (mine.length === 0 || mine.some((row) => row.status === 'opted_out')) continue; // not our customer, or confirmed before
    const waiting = mine.filter((row) => row.status === 'queued' || row.status === 'asked' || row.status === 'answered');
    const stopped = waiting.length > 0
      ? waiting.map((row) => save({ ...row, status: 'opted_out', note: 'asked to stop' }))
      : [save({ ...blankRow(), order_id: 'optout-' + digits(event.phone), customer_name: mine[0].customer_name, phone: event.phone, status: 'opted_out', note: 'asked to stop', created_at: nowIso })];
    say(stopped[0], 'optout', event.phone);
    continue;
  }

  const newest = (status, at) => mine.filter((row) => row.status === status).sort((a, b) => Date.parse(b[at]) - Date.parse(a[at]))[0];
  const target = newest('asked', 'asked_at') || newest('answered', 'answered_at');
  if (!target) continue;

  if (target.status === 'asked') {
    const score = parseScore(text);
    if (score === null) {
      if (target.reasks < 1) say(save({ ...target, reasks: 1 }), 'reask', target.phone);
      else save({ ...target, status: 'closed', note: 'no valid score after one re-ask' });
      continue;
    }
    const category = categoryOf(score);
    const comment = hasSentence(text) ? text : '';
    const entry = save({ ...target, score, category, comment, answered_at: nowIso, status: category === 'promoter' ? (comment ? 'commented' : 'closed') : comment ? 'commented' : 'answered' });
    if (category === 'promoter') {
      say(entry, 'promoter', target.phone);
    } else {
      if (category === 'detractor') say(entry, 'owner_alert', String(cfg.owner_phone).trim());
      if (category === 'detractor' && comment) say(entry, 'owner_comment', String(cfg.owner_phone).trim());
      if (category === 'detractor') say(entry, 'owner_card', String(cfg.owner_phone).trim());
      say(entry, comment ? 'comment_thanks' : category === 'passive' ? 'passive' : 'detractor', target.phone);
    }
  } else {
    // The score was given and the customer was asked why: whatever they write next is the comment.
    const entry = save({ ...target, comment: text, status: 'commented' });
    if (target.category === 'detractor') say(entry, 'owner_comment', String(cfg.owner_phone).trim());
    say(entry, 'comment_thanks', target.phone);
  }
}
return [...plans.values()].map((entry) => ({ json: { row: entry.row, messages: entry.messages } }));

// The one place that makes every text, from the wording in Your settings. Nothing is sent or saved here: it
// returns one item per message, and the nodes after it send them. A row that has no message to send stops here.
const cfg = $('Your settings').first().json;
const source = $('Check the settings').first().json.source;
const plans = (source === 'reply' ? $('Decide about the replies').all() : $('Decide what to do').all()).map((item) => item.json).filter((plan) => plan.row); // the week run may also hand on a clean-up item: it has no row
// {placeholders} are filled in; a typed backslash and n become a line break; a line whose only content was an empty
// placeholder (no order link) disappears.
const fill = (template, values) =>
  String(template)
    .replace(/\\n/g, '\n')
    .split('\n')
    .map((line) => ({ line, filled: line.replace(/\{(\w+)\}/g, (whole, name) => (name in values ? String(values[name]) : whole)) }))
    .filter(({ line, filled }) => line.trim() === '' || filled.trim() !== '')
    .map(({ filled }) => filled)
    .join('\n')
    .trim();
const reviewUrl = String(cfg.review_url ?? '').trim();
// Who is invited to leave a review: everyone who answered with a score (the link comes with the last thanks), or, only
// when the owner chooses it, the promoters alone.
const reviewForEveryone = String(cfg.review_for ?? 'everyone').trim().toLowerCase() !== 'promoters';

const out = [];
for (const { row, messages } of plans) {
  for (const message of messages) {
    const first = String(message.vars.customer_name || '').split(' ')[0] || String(cfg.name_fallback);
    const values = { ...message.vars, customer_name: message.vars.customer_name || message.vars.phone || 'a customer', name: first, business: cfg.business_name };
    const item = { order_id: row.order_id, purpose: message.purpose, kind: 'text', to: message.to, key: message.key, text: '', button_text: '', button_url: '', display_name: '', card_phone: '', row_after: row };
    switch (message.purpose) {
      case 'question': item.text = fill(cfg.msg_question, values); break;
      case 'reask': item.text = fill(cfg.msg_reask, values); break;
      case 'promoter':
        if (reviewUrl) {
          item.kind = 'button';
          item.text = fill(cfg.msg_promoter, values) + '\n' + fill(cfg.msg_review_invite, values);
          item.button_text = String(cfg.review_button_text).trim();
          item.button_url = reviewUrl;
        } else {
          item.text = fill(cfg.msg_promoter, values);
        }
        break;
      case 'passive': item.text = fill(cfg.msg_passive, values); break;
      case 'detractor': item.text = fill(cfg.msg_detractor, values); break;
      case 'comment_thanks':
        if (reviewUrl && reviewForEveryone) {
          item.kind = 'button';
          item.text = fill(cfg.msg_comment_thanks, values) + '\n' + fill(cfg.msg_review_invite, values);
          item.button_text = String(cfg.review_button_text).trim();
          item.button_url = reviewUrl;
        } else {
          item.text = fill(cfg.msg_comment_thanks, values);
        }
        break;
      case 'optout': item.text = fill(cfg.msg_optout_confirm, values); break;
      case 'owner_alert': item.text = fill(cfg.msg_owner_alert, values); break;
      case 'owner_comment': item.text = fill(cfg.msg_owner_comment, values); break;
      case 'owner_card':
        item.kind = 'card';
        item.display_name = String(message.vars.customer_name || message.vars.phone).slice(0, 200);
        item.card_phone = message.vars.phone;
        break;
      case 'report':
        item.text = fill(cfg.msg_report, values);
        // The same report sent again (a retry) has the same key and Turbo Notify returns the first message. A report
        // with other numbers (sent again on purpose, after its row was deleted) must not be refused as a conflict.
        item.key += '-' + [...item.text].reduce((hash, char) => Math.imul(hash ^ char.charCodeAt(0), ((1 << 24) + 0x193)) >>> 0, 0x811c9dc5).toString(16);
        break;
      default: throw new Error('Unknown message purpose: ' + message.purpose);
    }
    item.text = item.text.slice(0, item.kind === 'button' ? 1000 : 3500);
    out.push({ json: item });
  }
}
return out;

// Runs once, after every message of this run was sent or refused. Each answer of Turbo Notify is matched with the
// message that was planned for it, then written into the row of its survey: the id of the question, or the reason
// a message was refused. A refused send arrives here as an error: it never stopped the other messages.
const COLUMNS = ['order_id', 'customer_name', 'phone', 'status', 'score', 'comment', 'asked_at', 'answered_at', 'due_at', 'message_id', 'category', 'created_at', 'reasks', 'note', 'order_url', 'items'];
const blankRow = () => ({ order_id: '', customer_name: '', phone: '', status: '', score: null, comment: '', asked_at: '', answered_at: '', due_at: '', message_id: '', category: '', created_at: '', reasks: 0, note: '', order_url: '', items: '' });
const pick = (row) => {
  const out = blankRow();
  for (const name of COLUMNS) if (row[name] !== undefined && row[name] !== null) out[name] = row[name];
  out.score = row.score === undefined || row.score === null || row.score === '' ? null : Number(row.score);
  out.reasks = Number(row.reasks) || 0;
  return out;
};
const reasonOf = (error) => String(typeof error === 'string' ? error : (error && error.message) || JSON.stringify(error)).slice(0, 200);
// A refusal that waiting can cure: the number is not connected right now, Turbo Notify answered 5xx or not at all, the
// daily volume of a new number or the pace is used up. Such a question goes back to queued and is tried again at the
// next run (it is bounded by close_after_days: a survey that could not be sent in time is skipped). Anything else (a
// quota, a key without the scope, a reply ratio too low, a value Turbo Notify rejects) becomes send_failed: only a person can mend it.
const TEMPORARY = /\((?:number_not_connected|warmup_limit_exceeded|duplicate_burst_blocked|recipients_per_day_limit_exceeded|send_rate_spacing|rate_limit_exceeded|service_unavailable)\)|could not complete the request \(5\d\d\)|did not answer in time|could not reach turbo notify|too many requests/i;
const results = $input.all().map((answer, index) => {
  const planned = $('Write the messages').itemMatching(index).json;
  const failed = Boolean(answer.json.error) || !answer.json.id;
  return { planned, ok: !failed, message_id: failed ? '' : answer.json.id, error: failed ? reasonOf(answer.json.error || 'Turbo Notify did not return a message id') : '' };
});

const byOrder = new Map();
for (const result of results) {
  if (!byOrder.has(result.planned.order_id)) byOrder.set(result.planned.order_id, []);
  byOrder.get(result.planned.order_id).push(result);
}
const out = [];
for (const [, own] of byOrder) {
  const row = { ...own[0].planned.row_after };
  const failures = [];
  for (const result of own) {
    const purpose = result.planned.purpose;
    if (result.ok) {
      if (purpose === 'question') row.message_id = result.message_id;
      continue;
    }
    const to = purpose.startsWith('owner_') || purpose === 'report' ? 'the owner' : 'the customer';
    const again = purpose === 'question' && TEMPORARY.test(result.error);
    failures.push({ order_id: row.order_id, purpose, to, error: result.error + (again ? ' (the question stays queued and is tried again at the next run)' : '') });
    if (purpose === 'question') {
      // The question never reached the customer: it does not count for today's limit. A temporary refusal is tried again
      // by itself, any other one waits for a person.
      Object.assign(row, again ? { status: 'queued', asked_at: '', message_id: '', note: 'will try again, question not sent: ' + result.error } : { status: 'send_failed', asked_at: '', note: 'question not sent: ' + result.error });
    } else {
      row.note = [row.note, purpose + ' to ' + to + ' not sent: ' + result.error].filter(Boolean).join(' | ').slice(0, 500);
    }
  }
  out.push({ json: { ...pick(row), failures } });
}
return out;

// The last node of the run. A refused message is never silent: the row already says why, and this node makes the
// run fail so that your Error workflow (or the Executions list) shows it. It names the order and who was not
// reached, never a phone number.
const rows = $('Record the answers').all().map((item) => item.json);
const lines = [];
for (const row of rows) {
  for (const failure of row.failures) {
    lines.push(failure.purpose + ' for ' + (failure.order_id.startsWith('report-') ? 'the weekly report' : 'order ' + failure.order_id) + ' was not sent to ' + failure.to + ': ' + failure.error);
  }
}
if (lines.length > 0) throw new Error('Some messages were not sent. ' + lines.join(' || '));
return $input.all();
